104	    
105	    % Addition
106	    add_fmt = cl_fix_add_fmt(a_fmt, b_fmt);
107	    add_result = cl_fix_add(a, a_fmt, b, b_fmt, add_fmt);
108	    
109	    % Subtraction
110	    sub_fmt = cl_fix_sub_fmt(a_fmt, b_fmt);
111	    sub_result = cl_fix_sub(a, a_fmt, b, b_fmt, sub_fmt);
112	    
113	    % Add-sub
