120	    mult_result = cl_fix_mult(a, a_fmt, b, b_fmt, mult_fmt);
121	    
122	    % Absolute value
123	    abs_fmt = cl_fix_abs_fmt(a_fmt);
124	    abs_result = cl_fix_abs(a, a_fmt, abs_fmt);
125	    
126	    % Negative value
127	    neg_fmt = cl_fix_neg_fmt(a_fmt);
128	    neg_result = cl_fix_neg(a, a_fmt, neg_fmt);
129	    
130	    % Bit-shift
131	    shift_size = -3; % Negative value => right shift.
132	    shift_fmt = cl_fix_shift_fmt(a_fmt, shift_size);
133	    shift_result = cl_fix_shift(a, a_fmt, shift_size, shift_fmt);
134	    
135	    % ---------------------------------------------------------------------------------------------
136	    % Arithmetic Result Checking
137	    % ---------------------------------------------------------------------------------------------
138	    
139	    % All data formats in this script fit inside double-precision floats. This means we don't need
140	    % to handle arbitrary precision data.
141	    assert(~cl_fix_is_wide(a_fmt), 'Unexpected wide a_fmt.');
142	    assert(~cl_fix_is_wide(b_fmt), 'Unexpected wide b_fmt.');
143	    
144	    % Note: All of the example results are guaranteed to be represented without loss. So, we can
145	    % just check against ordinary double-precision arithmetic.
146	    
147	    % Addition
148	    assert(~cl_fix_is_wide(add_fmt), 'Unexpected wide add_fmt.');
149	    add_expected = a + b;
150	    assert(isequal(add_result, add_expected), 'Error in add');
151	    
152	    % Subtraction
153	    assert(~cl_fix_is_wide(sub_fmt), 'Unexpected wide sub_fmt.');
154	    sub_expected = a - b;
155	    assert(isequal(sub_result, sub_expected), 'Error in sub');
