167	    
168	    % Absolute value
169	    assert(~cl_fix_is_wide(abs_fmt), 'Unexpected wide abs_fmt.');
170	    abs_expected = abs(a);
171	    assert(isequal(abs_result, abs_expected), 'Error in abs');
172	    
173	    % Negation
174	    assert(~cl_fix_is_wide(neg_fmt), 'Unexpected wide neg_fmt.');
175	    neg_expected = -a;
176	    assert(isequal(neg_result, neg_expected), 'Error in neg');
177	    
178	    % Bit-shifting
179	    assert(~cl_fix_is_wide(shift_fmt), 'Unexpected wide shift_fmt.');
180	    shift_expected = a * 2^shift_size;
181	    assert(isequal(shift_result, shift_expected), 'Error in shift');
182	    
183	    % ---------------------------------------------------------------------------------------------
184	    % Misc Functions
185	    % ---------------------------------------------------------------------------------------------
186	    
187	    % Here, we mostly just check that Python function calls succeed without error. Functionality of
188	    % the Python implementation is tested separately.
189	    
190	    % Rounding
191	    round = Round.ConvEven_s;
192	    round_fmt = cl_fix_round_fmt(a_fmt, a_fmt.F - 4, round);
193	    round_result = cl_fix_round(a, a_fmt, round_fmt, round);
194	    
195	    % Saturation
196	    saturate = Sat.Sat_s;
197	    sat_fmt = cl_fix_format(0, a_fmt.I - 4, a_fmt.F);
198	    sat_result = cl_fix_saturate(a, a_fmt, sat_fmt, saturate);
199	    
200	    % Rounding and saturation
201	    resize_result = cl_fix_resize(a, a_fmt, b_fmt, round, saturate);
202	    
203	    % Bit-width
204	    assert(cl_fix_width(a_fmt) == a_fmt.S + a_fmt.I + a_fmt.F, 'Unexpected a_fmt width.');
205	    assert(cl_fix_width(b_fmt) == b_fmt.S + b_fmt.I + b_fmt.F, 'Unexpected b_fmt width.');
206	    
207	    % Integer representations
208	    a_int = cl_fix_to_integer(a, a_fmt);
209	    a_check = cl_fix_from_integer(a_int, a_fmt);
210	    assert(isequal(a_check, a), 'Unexpected values after integer conversions.');
211	    
212	    % Conversion from float
213	    a_check = cl_fix_from_real(a, a_fmt, Sat.SatWarn_s);
214	    assert(isequal(a_check, a), 'Unexpected values after float conversions');
